import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const q=JSON.parse('{"title":"QQ","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/channels/qq.md","filePath":"ja/integrations/channels/qq.md","lastUpdated":1792323081000}'),n={name:"ja/integrations/channels/qq.md"};function l(s,t,i,d,h,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="qq" tabindex="-1">QQ <a class="header-anchor" href="#qq" aria-label="Permalink to &quot;QQ&quot;">​</a></h1><p>QQ オープンプラットフォームの公式 Bot を通じて Memoh を QQ につなぎます。プライベートチャット、グループチャット、話題（スレッド）での会話に対応します。</p><div class="warning custom-block"><p class="custom-block-title">使用制限</p><ul><li>1 つの QQ アカウントで作成できる Bot は最大 5 個です。</li><li>返信は完全なメッセージブロック単位で届き、token ごとのストリーミング出力は行われません。</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>QQ アカウント。<a href="https://q.qq.com/qqbot/openclaw/" target="_blank" rel="noreferrer">QQ Bot オープンプラットフォーム</a> へのログインに使います。</li></ul><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><h3 id="_1-qq-オープンプラットフォームで-bot-を作成する" tabindex="-1">1. QQ オープンプラットフォームで Bot を作成する <a class="header-anchor" href="#_1-qq-オープンプラットフォームで-bot-を作成する" aria-label="Permalink to &quot;1. QQ オープンプラットフォームで Bot を作成する&quot;">​</a></h3><p>QQ Bot オープンプラットフォームで次を行います。</p><ol><li><a href="https://q.qq.com/qqbot/openclaw/" target="_blank" rel="noreferrer">QQ Bot オープンプラットフォーム</a> を開き、QQ アカウントでログインします。</li><li><strong>创建机器人</strong>（Create Bot）をクリックします。審査は不要です。</li><li>ページに表示される <strong>AppID</strong> と <strong>AppSecret</strong> をコピーします。<strong>AppSecret</strong> は一度しか表示されないので、必ず安全に保管してください。</li></ol><blockquote><p>公式リソース：<a href="https://q.qq.com/" target="_blank" rel="noreferrer">QQ Bot オープンプラットフォーム</a> · <a href="https://bot.q.qq.com/wiki/" target="_blank" rel="noreferrer">QQ Bot ドキュメント</a></p></blockquote><h3 id="_2-memoh-でチャネルを追加する" tabindex="-1">2. Memoh でチャネルを追加する <a class="header-anchor" href="#_2-memoh-でチャネルを追加する" aria-label="Permalink to &quot;2. Memoh でチャネルを追加する&quot;">​</a></h3><p>Memoh で次を行います。</p><ol><li>Bot の <strong>プラットフォーム</strong> タブを開きます。</li><li><strong>Add Channel</strong> をクリックし、<strong>QQ</strong> を選択します。</li><li><strong>AppID</strong> と <strong>AppSecret</strong> を貼り付けます。</li><li>必要に応じてオプション設定を調整します。<strong>Markdown Support</strong> と <strong>Enable Input Hint</strong> はどちらもデフォルトで有効です。</li><li><strong>Save and Enable</strong> をクリックします。</li></ol><h2 id="認証情報" tabindex="-1">認証情報 <a class="header-anchor" href="#認証情報" aria-label="Permalink to &quot;認証情報&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>必須</th><th>説明</th></tr></thead><tbody><tr><td><strong>AppID</strong></td><td>はい</td><td>Bot の App ID。Bot 作成時に QQ オープンプラットフォームのページに表示されます。</td></tr><tr><td><strong>AppSecret</strong></td><td>はい</td><td>Bot の App Secret。作成時に一度だけ表示されます。</td></tr><tr><td><strong>Markdown Support</strong></td><td>いいえ</td><td>Markdown 形式を有効にします（デフォルト：有効）。</td></tr><tr><td><strong>Enable Input Hint</strong></td><td>いいえ</td><td>返信の生成中に「入力中」の表示を出します（デフォルト：有効）。</td></tr></tbody></table><h2 id="動作確認" tabindex="-1">動作確認 <a class="header-anchor" href="#動作確認" aria-label="Permalink to &quot;動作確認&quot;">​</a></h2><p>プライベートチャットで Bot に <code>/help</code> を送るか、グループチャットで Bot を @メンションして <code>/help</code> を送ります。Bot がコマンド一覧を返せば、チャネルは接続できています。</p><h2 id="グループチャット" tabindex="-1">グループチャット <a class="header-anchor" href="#グループチャット" aria-label="Permalink to &quot;グループチャット&quot;">​</a></h2><p>Bot は QQ のグループチャットと話題（スレッド）での会話に対応しています。グループ内で Bot を @メンションすると返信します。</p><h2 id="無効化と認証情報の更新" tabindex="-1">無効化と認証情報の更新 <a class="header-anchor" href="#無効化と認証情報の更新" aria-label="Permalink to &quot;無効化と認証情報の更新&quot;">​</a></h2><p>Bot の <strong>プラットフォーム</strong> タブから、いつでもこのチャネルを無効化・削除できます。認証情報を更新するときは、同じパネルで <strong>AppID</strong> / <strong>AppSecret</strong> を更新して保存してください。</p><h2 id="faq" tabindex="-1">よくある質問 <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;よくある質問 {#faq}&quot;">​</a></h2><h3 id="appsecret-reset" tabindex="-1">AppSecret が分からなくなった <a class="header-anchor" href="#appsecret-reset" aria-label="Permalink to &quot;AppSecret が分からなくなった {#appsecret-reset}&quot;">​</a></h3><p><strong>AppSecret</strong> は Bot 作成時に一度しか表示されません。QQ オープンプラットフォームで再度表示しようとすると強制的にリセットされます。リセット後は、Memoh で <strong>AppSecret</strong> を更新して保存してください。</p>',24)])])}const g=e(n,[["render",l]]);export{q as __pageData,g as default};
